function renderRecovery(){
 const r=sessionRecovery(),mins=sleepMinutes(r.bed,r.wake),hrs=sleepHours(r);
 $('recovery').innerHTML=`<h2>Recovery check-in</h2><div class="card stack">${dailyDateInput()}<p class="hint">Log once per day. Your workout sets automatically use this check-in, so you don't have to enter sleep and carbs repeatedly.</p><div class="grid"><div><label class="label">Went to sleep</label><input type="time" id="sleepTime" value="${escapeHtml(r.bed||'')}"></div><div><label class="label">Woke up</label><input type="time" id="wakeTime" value="${escapeHtml(r.wake||'')}"></div></div><div class="kpi"><div class="tag">Time between sleep and wake</div><div class="big" id="sleepResult">${hrs==null?'—':sleepText(Math.round(hrs*60))}</div><div class="hint" id="sleepExplain">${mins!=null?'Overnight times automatically cross midnight.':'Add both times to calculate time in bed.'}${mins==null&&positive(r.legacyHours)?' Imported historical sleep estimate shown above.':''}</div></div><div class="row"><label for="carbRange">Pre-workout carbohydrates</label><strong id="carbAmount">${n(r.precarbs||0)} g</strong></div><input type="range" id="carbRange" min="0" max="150" step="5" value="${Math.min(150,+r.precarbs||0)}"><label class="label">Precise amount (g)</label><input id="carbsNumber" type="number" min="0" max="1000" step="1" value="${n(r.precarbs||0)}"><div class="row"><label for="readyRange">Readiness</label><strong id="readyValue">${n(r.readiness||3)} / 5</strong></div><input type="range" id="readyRange" min="1" max="5" step="1" value="${r.readiness||3}"><div class="row"><label for="soreRange">Muscle soreness</label><strong id="soreValue">${n(r.soreness||1)} / 5</strong></div><input type="range" id="soreRange" min="1" max="5" step="1" value="${r.soreness||1}"><label class="label">Session notes (optional)</label><textarea id="recoveryNotes" rows="3" placeholder="Energy, stress, illness, training context…">${escapeHtml(r.notes||'')}</textarea><button class="btn" id="saveRecovery">Save recovery check-in</button></div><div class="notice-info"><strong>What the sleep calculator measures:</strong> It calculates elapsed time between the two times, including overnight periods. This is <em>time in bed</em> rather than measured sleep if you took time to fall asleep or woke during the night.</div>`;
 bindDate();
 function updateSleep(){const minutes=sleepMinutes($('sleepTime').value,$('wakeTime').value);$('sleepResult').textContent=minutes==null?'—':sleepText(minutes);$('sleepExplain').textContent=minutes==null?'Enter both times to calculate.':minutes===0?'Times are equal—please check them.':'Calculated across midnight automatically when appropriate.'}
 listen('sleepTime','input',updateSleep);listen('wakeTime','input',updateSleep);
 listen('carbRange','input',e=>{$('carbsNumber').value=e.target.value;$('carbAmount').textContent=e.target.value+' g'});listen('carbsNumber','input',e=>{const v=+e.target.value||0;$('carbRange').value=Math.min(150,v);$('carbAmount').textContent=n(v)+' g'});
 listen('readyRange','input',e=>{$('readyValue').textContent=e.target.value+' / 5'});listen('soreRange','input',e=>{$('soreValue').textContent=e.target.value+' / 5'});
 listen('saveRecovery','click',()=>{const bed=$('sleepTime').value,wake=$('wakeTime').value,minutes=sleepMinutes(bed,wake);if((bed&&!wake)||(!bed&&wake))return notify('Enter both sleep and wake times, or leave both blank.');if(minutes===0&&bed&&wake)return notify('Sleep and wake times are identical.');db.recovery[db.selectedDate]={bed,wake,legacyHours:(!bed&&!wake&&positive(r.legacyHours))?r.legacyHours:null,precarbs:Math.max(0,Number($('carbsNumber').value)||0),readiness:+$('readyRange').value,soreness:+$('soreRange').value,notes:$('recoveryNotes').value.slice(0,1200),savedAt:new Date().toISOString()};persist();renderRecovery();notify('✓ Recovery check-in saved')});
}
function sessionStrengthChanges(date){const session=db.sets.filter(x=>x.date===date),groups=[...new Set(session.map(s=>s.muscle+'\u0000'+lower(s.exercise)))];return groups.map(key=>{const [m,ex]=key.split('\u0000');const current=session.filter(s=>sameExercise(s,m,ex));const currentBest=current.reduce((x,y)=>e1rm(x)>=e1rm(y)?x:y);const dates=[...new Set(db.sets.filter(s=>sameExercise(s,m,ex)&&s.date<date).map(x=>x.date))].sort();if(!dates.length)return null;const lastDate=dates[dates.length-1];const prior=db.sets.filter(s=>sameExercise(s,m,ex)&&s.date===lastDate);const priorBest=prior.reduce((x,y)=>e1rm(x)>=e1rm(y)?x:y);return {muscle:m,exercise:currentBest.exercise,lastDate,currentBest,priorBest,change:e1rm(priorBest)>0?(e1rm(currentBest)/e1rm(priorBest)-1)*100:0}}).filter(Boolean)}
function chartPath(sets){if(sets.length<2)return '';const min=Math.min(...sets),max=Math.max(...sets),span=Math.max(.01,max-min);return sets.map((value,i)=>`${i===0?'M':'L'}${(i/(sets.length-1)*300).toFixed(1)},${(60-(value-min)/span*48).toFixed(1)}`).join(' ')}
function renderInsights(){
 const sets=currentSets(),changes=sessionStrengthChanges(db.selectedDate),r=sessionRecovery(),hrs=sleepHours(r),f=currentFoods();const recentDate=dateBack(db.selectedDate,6),recent=db.sets.filter(s=>s.date>=recentDate&&s.date<=db.selectedDate);const groups=[...new Set(recent.map(s=>s.muscle))].sort();const feedback=[];
 if(hrs!=null&&hrs<6.5)feedback.push(['Sleep below your usual target','You logged less than 6.5 hours between sleep and wake. Compare performance across several nights before drawing conclusions.']);
 if(Number(r.soreness)>=4)feedback.push(['High soreness','Consider whether soreness is changing your range of motion or performance.']);
 if(sets.length>=2&&sets.filter(s=>Number(s.rir)===0).length/sets.length>=.75)feedback.push(['Many failure sets','Most recorded sets reached failure. Monitor whether this reduces reps later in the session or at your next exposure.']);
 if(sets.some(s=>Number(s.rest)<120))feedback.push(['Short rest intervals','At least one working set had under two minutes of rest. Longer rests may improve repeat-set performance.']);
 if(sets.some(s=>Number(s.reps)<6))feedback.push(['Below target repetitions','At least one set was under your usual 6–10-rep range. Consider adjusting load or rest.']);
 if(sets.some(s=>Number(s.reps)>10))feedback.push(['Over target repetitions','A working set exceeded ten reps. Consider a small load increase when technique is consistent.']);
 if(changes.length){const downs=changes.filter(x=>x.change<=-5),ups=changes.filter(x=>x.change>=5);if(downs.length)feedback.push(['Performance down on '+downs.length+' exercise(s)','Estimated strength was at least 5% lower than the previous logged session. This is a signal to review, not proof of poor recovery.']);if(ups.length)feedback.push(['Performance improving','Estimated strength increased at least 5% in '+ups.length+' exercise(s). Keep technique and effort consistent for meaningful comparisons.']);}
 if(!sets.length)feedback.push(['Ready for your first session','Record a workout on the selected date to unlock comparisons, and log recovery information once in the Recovery tab.']);
 $('insights').innerHTML=`<h2>Training intelligence</h2><div class="card stack">${dailyDateInput()}<div class="grid"><div class="kpi"><div class="tag">Working sets</div><div class="stat">${sets.length}</div></div><div class="kpi"><div class="tag">Load-volume</div><div class="stat">${n(volumeOf(sets)*weightFactor())}</div><div class="hint">${db.weightUnit} × reps</div></div></div><div class="grid"><div class="kpi"><div class="tag">Time in bed</div><div class="stat">${hrs==null?'—':sleepText(Math.round(hrs*60))}</div></div><div class="kpi"><div class="tag">Pre-workout carbs</div><div class="stat">${n(r.precarbs||0)}g</div></div></div></div>
 <h3>Session-over-session strength</h3><div class="card">${changes.length?changes.map(x=>`<div class="listitem"><div class="row"><strong class="small">${escapeHtml(x.exercise)}</strong><span class="pill ${x.change>=1?'good':x.change<=-5?'warning':''}">${x.change>0?'+':''}${n(x.change,1)}%</span></div><div class="hint">${escapeHtml(x.muscle)} · Compared with ${escapeHtml(x.lastDate)} · Estimated 1RM, not measured 1RM</div></div>`).join(''):'<p class="hint">Log the same exercise on two different dates to see estimated strength changes.</p>'}</div>
 <h3>Session feedback</h3>${feedback.length?feedback.map(([title,body])=>`<div class="card"><div class="row start"><span class="circle" style="margin-top:5px"></span><div style="flex:1"><strong class="small">${escapeHtml(title)}</strong><p class="hint" style="margin:6px 0 0">${escapeHtml(body)}</p></div></div></div>`).join(''):'<div class="card"><p class="hint">No major flags based on the available data. Keep logging consistent load, technique and rest intervals.</p></div>'}
 <h3>Direct working sets · last seven days</h3><div class="card">${groups.length?groups.map(m=>{const v=recent.filter(x=>x.muscle===m).length;return `<div style="margin-bottom:12px"><div class="row small"><span>${escapeHtml(m)}</span><strong>${v} sets</strong></div><div class="bar" style="margin-top:5px"><span style="width:${Math.min(100,v/12*100)}%"></span></div></div>`}).join(''):'<p class="hint">No training sets recorded in this seven-day window.</p>'}</div><div class="notice-info"><strong>Interpretation:</strong> These rules highlight patterns; they do not diagnose fatigue or predict muscle growth. Estimated 1RM is most informative when reps, technique, and exercise conditions are comparable. Food totals for this date: ${n(sum(f,'kcal'))} kcal, ${n(sum(f,'p'))}g protein, ${n(sum(f,'c'))}g carbs.</div>`;
 bindDate();
}
