 listen('addMuscle','click',()=>{const name=$('newMuscle').value.trim();if(!name)return notify('Enter a muscle group name.');if(db.muscleGroups.some(m=>lower(m)===lower(name)))return notify('That muscle group already exists.');db.muscleGroups.push(name);db.exerciseLibrary[name]=db.exerciseLibrary[name]||[];db.archivedMuscles=db.archivedMuscles.filter(m=>m!==name);persist();renderSettings();notify('✓ Muscle group added')});listen('newMuscle','keydown',e=>{if(e.key==='Enter')$('addMuscle').click()});
