 listen('restoreMuscles','click',()=>{for(const m of Object.keys(PRESET_EXERCISES)){if(!db.muscleGroups.includes(m))db.muscleGroups.push(m);if(!Array.isArray(db.exerciseLibrary[m]))db.exerciseLibrary[m]=[];db.archivedMuscles=db.archivedMuscles.filter(x=>x!==m)}persist();renderSettings();notify('Original muscle groups restored')});
 document.querySelectorAll('[data-split-day]').forEach(b=>b.onchange=()=>{const i=Number(b.dataset.splitDay),m=b.dataset.splitMuscle;db.split[i].muscles=b.checked?[...new Set([...db.split[i].muscles,m])]:db.split[i].muscles.filter(x=>x!==m);persist();const parent=b.closest('details');const open=parent?.open;renderSettings();const details=$('settings').querySelectorAll('details.spliteditor')[i];if(details)details.open=Boolean(open);notify('Split updated')});
 listen('resetSplit','click',()=>{if(!confirm('Restore your original Sunday–Thursday split? Custom muscle groups and workout history will remain.'))return;for(const m of Object.keys(PRESET_EXERCISES))if(!db.muscleGroups.includes(m))db.muscleGroups.push(m);db.archivedMuscles=db.archivedMuscles.filter(m=>!Object.keys(PRESET_EXERCISES).includes(m));db.split=deepClone(ORIGINAL_SPLIT);persist();renderSettings();notify('Original split restored')});
