 listen('importBackup','change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(!obj||!Array.isArray(obj.sets)||!Array.isArray(obj.foods))throw new Error('Not a StrengthLab backup');if(!confirm('Replace all local StrengthLab records with this backup?'))return;db=migrate(obj);persist();setTheme();ui.exerciseText='';ui.muscle='';renderSettings();notify('✓ Backup imported')}catch(err){notify('Import failed: '+err.message)}});
 listen('clearData','click',()=>{if(!confirm('Delete ALL locally stored foods, exercises, workouts and recovery data? Export a backup first.'))return;db=defaults();persist();setTheme();renderSettings();notify('Local records cleared')});
